#!/usr/local/bin/prhm-node
'use strict';
const fs=require('node:fs');
const path=require('node:path');
const crypto=require('node:crypto');
const cp=require('node:child_process');

const ACTION='solo_company_runtime_install_surface_v1';
const EXPECTED_REGISTRY_SHA='0d69b284f8bcf9b772a711dff962a614bd0c1234ee03b87f3faa70877eadb48c';
const IMMUTABLE_HOST_ACTIONS_V2_SHA='597701ccc1a6c39d54aef9bd22d1c8732c88536e36e12251511a509bde439b46';
const SOLO_PLUGIN_SHA='60cac9151ab434ff0b5a0f8c86651a226f8478a6c825a0513fd2a88c1c20ea5f';
const SOLO_CORE_SHA='9e4139c7b8f126284c8aaced743e5daecb49fafd0c4a41bde47d61cbc4ffe223';
const PATHS=Object.freeze({registry:'/home/agent/ssh-mcp-server/src/core/registry.js',hostActionsV2:'/home/agent/ssh-mcp-server/src/plugins/hostActionsV2.js',soloPlugin:'/home/agent/ssh-mcp-server/src/plugins/soloCompanyRuntimeInstall.js',soloCore:'/home/agent/ssh-mcp-server/src/plugins/soloCompanyRuntimeInstallCore.js'});
const SOLO_PLUGIN_B64='';
const SOLO_CORE_B64='';
const IMPORT_ANCHOR="import { registerHonartikIticketPreflightPlugin } from '../plugins/honartikIticketPreflight.js';";
const REGISTER_ANCHOR='  registerHonartikIticketPreflightPlugin(mcp, context);';
const IMPORT_LINE="import { registerSoloCompanyRuntimeInstallPlugin } from '../plugins/soloCompanyRuntimeInstall.js';";
const REGISTER_LINE='  registerSoloCompanyRuntimeInstallPlugin(mcp, context);';
const H=b=>crypto.createHash('sha256').update(b).digest('hex');
const fail=m=>{throw new Error(m)};
const count=(s,n)=>s.split(n).length-1;
function readBytes(f){const st=fs.lstatSync(f);if(!st.isFile()||st.isSymbolicLink()||fs.realpathSync(f)!==f)fail('not_regular:'+f);return fs.readFileSync(f)}
function shaFile(f){return H(readBytes(f))}
function replaceOnce(s,a,b,label){if(count(s,a)!==1)fail(label+'_anchor_'+count(s,a));return s.replace(a,b)}
function patchRegistry(source){
  if(source.includes(IMPORT_LINE)||source.includes(REGISTER_LINE))fail('already_patched');
  let out=replaceOnce(source,IMPORT_ANCHOR,IMPORT_ANCHOR+'\n'+IMPORT_LINE,'registry_import');
  out=replaceOnce(out,REGISTER_ANCHOR,REGISTER_ANCHOR+'\n'+REGISTER_LINE,'registry_register');
  if(count(out,IMPORT_LINE)!==1||count(out,REGISTER_LINE)!==1)fail('registry_postcondition');
  return out;
}
function embedded(b64,want,label){const b=Buffer.from(b64,'base64');if(H(b)!==want)fail('embedded_'+label+'_sha_mismatch');return b}
function syntaxSource(label,bytes){const f='/tmp/prhm-v25-'+label+'-'+process.pid+'-'+Date.now()+'.mjs';fs.writeFileSync(f,bytes,{mode:0o600,flag:'wx'});try{const r=cp.spawnSync('/usr/local/bin/prhm-node',['--check',f],{encoding:'utf8',timeout:20000,maxBuffer:120000});if(r.error||r.status!==0)fail('syntax_'+label+':'+String(r.stderr||r.stdout||r.error?.message||''));}finally{try{fs.unlinkSync(f)}catch{}}}
function validateInstalled(){
  const p=fs.existsSync(PATHS.soloPlugin),c=fs.existsSync(PATHS.soloCore);if(p!==c)fail('partial_install_present');if(!p)return null;
  if(shaFile(PATHS.soloPlugin)!==SOLO_PLUGIN_SHA||shaFile(PATHS.soloCore)!==SOLO_CORE_SHA)fail('installed_solo_sha_mismatch');
  if(shaFile(PATHS.hostActionsV2)!==IMMUTABLE_HOST_ACTIONS_V2_SHA)fail('host_actions_v2_drift');
  const r=readBytes(PATHS.registry).toString('utf8');if(count(r,IMPORT_LINE)!==1||count(r,REGISTER_LINE)!==1)fail('installed_registry_binding_invalid');
  return {ok:true,action:ACTION,already_installed:true,solo_plugin_sha256:SOLO_PLUGIN_SHA,solo_core_sha256:SOLO_CORE_SHA,host_actions_v2_sha256:IMMUTABLE_HOST_ACTIONS_V2_SHA,requires_zdt_refresh:true,production_application_mutation:false,database_mutation:false};
}
function preflight(){
  const prior=validateInstalled();if(prior)return {...prior,preflight_only:true};
  if(shaFile(PATHS.registry)!==EXPECTED_REGISTRY_SHA)fail('registry_baseline_sha_mismatch:'+shaFile(PATHS.registry));
  if(shaFile(PATHS.hostActionsV2)!==IMMUTABLE_HOST_ACTIONS_V2_SHA)fail('host_actions_v2_sha_mismatch:'+shaFile(PATHS.hostActionsV2));
  const plugin=embedded(SOLO_PLUGIN_B64,SOLO_PLUGIN_SHA,'plugin'),core=embedded(SOLO_CORE_B64,SOLO_CORE_SHA,'core');
  const patched=patchRegistry(readBytes(PATHS.registry).toString('utf8'));
  syntaxSource('plugin',plugin);syntaxSource('core',core);syntaxSource('registry',Buffer.from(patched));
  return {ok:true,action:ACTION,preflight_only:true,already_installed:false,baseline_match:true,current_registry_sha256:EXPECTED_REGISTRY_SHA,host_actions_v2_sha256:IMMUTABLE_HOST_ACTIONS_V2_SHA,candidate_registry_sha256:H(Buffer.from(patched)),solo_plugin_sha256:SOLO_PLUGIN_SHA,solo_core_sha256:SOLO_CORE_SHA,requires_zdt_refresh:true,production_application_mutation:false,database_mutation:false,service_control:false};
}
function atomicCreate(file,bytes,mode,uid,gid){fs.mkdirSync(path.dirname(file),{recursive:true,mode:0o755});const t=file+'.v25-'+process.pid+'-'+Date.now()+'.tmp';const fd=fs.openSync(t,'wx',mode);try{fs.writeFileSync(fd,bytes);fs.fsyncSync(fd)}finally{fs.closeSync(fd)}fs.chmodSync(t,mode);if(Number.isInteger(uid)&&Number.isInteger(gid))fs.chownSync(t,uid,gid);fs.renameSync(t,file)}
function atomicReplace(file,bytes,st){const t=file+'.v25-'+process.pid+'-'+Date.now()+'.tmp';const fd=fs.openSync(t,'wx',st.mode&0o777);try{fs.writeFileSync(fd,bytes);fs.fsyncSync(fd)}finally{fs.closeSync(fd)}fs.chownSync(t,st.uid,st.gid);fs.renameSync(t,file)}
function install(){
  const prior=validateInstalled();if(prior)return prior;
  const pf=preflight();
  const registryBytes=readBytes(PATHS.registry),registryStat=fs.statSync(PATHS.registry),plugin=embedded(SOLO_PLUGIN_B64,SOLO_PLUGIN_SHA,'plugin'),core=embedded(SOLO_CORE_B64,SOLO_CORE_SHA,'core'),patched=Buffer.from(patchRegistry(registryBytes.toString('utf8')));
  const stamp=new Date().toISOString().replace(/[-:.TZ]/g,'').slice(0,14),backupDir='/var/backups/prhm-host-actions-v25-solo-runtime-installer-'+stamp;fs.mkdirSync(backupDir,{recursive:false,mode:0o700});const backup=path.join(backupDir,'registry.js.bak');fs.writeFileSync(backup,registryBytes,{flag:'wx',mode:0o600});
  let pluginCreated=false,coreCreated=false,registryChanged=false;
  try{
    atomicCreate(PATHS.soloCore,core,0o644,registryStat.uid,registryStat.gid);coreCreated=true;if(shaFile(PATHS.soloCore)!==SOLO_CORE_SHA)fail('solo_core_post_sha');
    atomicCreate(PATHS.soloPlugin,plugin,0o644,registryStat.uid,registryStat.gid);pluginCreated=true;if(shaFile(PATHS.soloPlugin)!==SOLO_PLUGIN_SHA)fail('solo_plugin_post_sha');
    atomicReplace(PATHS.registry,patched,registryStat);registryChanged=true;
    if(shaFile(PATHS.hostActionsV2)!==IMMUTABLE_HOST_ACTIONS_V2_SHA)fail('host_actions_v2_changed');
    const final=validateInstalled();
    return {...final,installed:true,already_installed:false,backup_dir:backupDir,registry_sha256:shaFile(PATHS.registry),preflight:pf,requires_zdt_refresh:true,service_control:false,rollback_performed:false};
  }catch(error){
    const rb=[];if(registryChanged)try{atomicReplace(PATHS.registry,fs.readFileSync(backup),registryStat)}catch(e){rb.push('registry:'+e.message)}
    if(pluginCreated)try{fs.unlinkSync(PATHS.soloPlugin)}catch(e){rb.push('plugin:'+e.message)}
    if(coreCreated)try{fs.unlinkSync(PATHS.soloCore)}catch(e){rb.push('core:'+e.message)}
    if(rb.length)fail('install_failed_and_rollback_failed:'+String(error.message||error)+':'+rb.join('|'));
    fail('install_failed_rolled_back:'+String(error.message||error));
  }
}
if(require.main===module){const arg=process.argv[2];const out=arg==='--preflight-only'?preflight():arg==='--apply'?install():fail('mode_required');console.log(JSON.stringify(out));}
module.exports={ACTION,EXPECTED_REGISTRY_SHA,IMMUTABLE_HOST_ACTIONS_V2_SHA,SOLO_PLUGIN_SHA,SOLO_CORE_SHA,PATHS,SOLO_PLUGIN_B64,SOLO_CORE_B64,patchRegistry,preflight,install};
